# Let's think about what basic replacements could be applied
# First, let's check if we can identify simple character mappings

inputs = ['vyfxaf', 'xw', 'huy', 'wvv', 'cvkkv']
outputs = ['iafeyxafey', 'feyfeyd', 'huy', 'cwbvv', 'cvkkv']

# Analyze character-by-character changes
replacements = {}

for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in replacements:
                replacements[inp[i]] = outp[i]
            else:
                # If already mapped, check if consistent
                if replacements[inp[i]] != outp[i]:
                    print(f"Conflict: '{inp[i]}' maps to both '{replacements[inp[i]]}' and '{outp[i]}'")

print("Character mappings found:")
for char, replacement in replacements.items():
    print(f"  '{char}' → '{replacement}'")

# Now let's check for patterns in the longer sequences
print("\nChecking specific patterns:")

# For 'vyfxaf' → 'iafeyxafey'
print("vyfxaf → iafeyxafey")
print("Positions where chars differ:")
for i in range(min(len('vyfxaf'), len('iafeyxafey'))):
    if 'vyfxaf'[i] != 'iafeyxafey'[i]:
        print(f"  Position {i}: '{'vyfxaf'[i]}' → '{'iafeyxafey'[i]}'")

# For 'xw' → 'feyfeyd'
